<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$msg='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$type=(string)($_POST['document_type']??'terms');$version=trim((string)$_POST['version']);$content=trim((string)$_POST['content']);$effective=str_replace('T',' ',(string)$_POST['effective_at']).':00';if(in_array($type,['terms','privacy'],true)&&$version!==''&&$content!==''){$db->execute('INSERT INTO legal_documents(document_type,version,content,required,effective_at) VALUES(?,?,?,?,?)',[$type,$version,$content,isset($_POST['required'])?1:0,$effective]);$audit->write('legal_document.created','success',(int)$admin['id'],null,null,null,['type'=>$type,'version'=>$version]);$msg='<div class="alert success">Dokument zapisany.</div>';}}
$rows='';foreach($db->all('SELECT * FROM legal_documents ORDER BY effective_at DESC,id DESC') as $d)$rows.='<tr><td>'.Web::e($d['document_type']).'</td><td>'.Web::e($d['version']).'</td><td>'.((bool)$d['required']?'Wymagany':'Opcjonalny').'</td><td>'.Web::e($d['effective_at']).'</td></tr>';Web::page('Terms / Privacy','<div class="page-head"><div><h1>Terms of Service / Privacy Policy</h1><p>Wersjonowane dokumenty i obowiązkowa akceptacja.</p></div></div>'.$msg.'<section class="card"><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Typ<select name="document_type"><option value="terms">Terms</option><option value="privacy">Privacy</option></select></label><label>Wersja<input name="version" required></label><label>Treść<textarea name="content" rows="10" required></textarea></label><label>Obowiązuje od<input type="datetime-local" name="effective_at" required></label><label><input type="checkbox" name="required" checked> Wymagaj akceptacji</label><button class="primary">Dodaj wersję</button></form></section><div class="table-wrap"><table><thead><tr><th>Typ</th><th>Wersja</th><th>Tryb</th><th>Od</th></tr></thead><tbody>'.$rows.'</tbody></table></div>',$admin);
